DROP VIEW IF EXISTS current_accounting_dimension_definitions;
DROP VIEW IF EXISTS current_accounting_dimension_members;
DROP TRIGGER IF EXISTS accounting_dimension_definition_events_no_update;
DROP TRIGGER IF EXISTS accounting_dimension_definition_events_no_delete;
DROP TRIGGER IF EXISTS accounting_dimension_member_events_no_update;
DROP TRIGGER IF EXISTS accounting_dimension_member_events_no_delete;
ALTER TABLE accounting_dimension_definition_events RENAME TO accounting_dimension_definition_events_v28;
CREATE TABLE accounting_dimension_definition_events (id INTEGER PRIMARY KEY,dimension_id TEXT NOT NULL,kind TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','inactive','superseded')),event_type TEXT NOT NULL CHECK(event_type IN ('defined','activated','deactivated','renamed','superseded')),supersedes_dimension_id TEXT,actor TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL);
INSERT INTO accounting_dimension_definition_events(id,dimension_id,kind,name,status,event_type,actor,principal,created_at) SELECT id,dimension_id,kind,name,'active',event_type,actor,principal,created_at FROM accounting_dimension_definition_events_v28;
DROP TABLE accounting_dimension_definition_events_v28;
ALTER TABLE accounting_dimension_member_events RENAME TO accounting_dimension_member_events_v28;
CREATE TABLE accounting_dimension_member_events (id INTEGER PRIMARY KEY,dimension_id TEXT NOT NULL,member_id TEXT NOT NULL,name TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('active','inactive','superseded')),effective_from TEXT,effective_to TEXT,event_type TEXT NOT NULL CHECK(event_type IN ('defined','activated','deactivated','renamed','superseded')),supersedes_member_id TEXT,actor TEXT NOT NULL,principal TEXT NOT NULL,created_at TEXT NOT NULL);
INSERT INTO accounting_dimension_member_events(id,dimension_id,member_id,name,status,effective_from,effective_to,event_type,actor,principal,created_at) SELECT id,dimension_id,member_id,name,status,effective_from,effective_to,event_type,actor,principal,created_at FROM accounting_dimension_member_events_v28;
DROP TABLE accounting_dimension_member_events_v28;
CREATE VIEW current_accounting_dimension_definitions AS SELECT e.* FROM accounting_dimension_definition_events e WHERE e.id=(SELECT MAX(x.id) FROM accounting_dimension_definition_events x WHERE x.dimension_id=e.dimension_id);
CREATE VIEW current_accounting_dimension_members AS SELECT e.* FROM accounting_dimension_member_events e WHERE e.id=(SELECT MAX(x.id) FROM accounting_dimension_member_events x WHERE x.dimension_id=e.dimension_id AND x.member_id=e.member_id);
CREATE TRIGGER accounting_dimension_definition_events_no_update BEFORE UPDATE ON accounting_dimension_definition_events BEGIN SELECT RAISE(ABORT,'accounting dimension definition events are append-only'); END;
CREATE TRIGGER accounting_dimension_definition_events_no_delete BEFORE DELETE ON accounting_dimension_definition_events BEGIN SELECT RAISE(ABORT,'accounting dimension definition events are append-only'); END;
CREATE TRIGGER accounting_dimension_member_events_no_update BEFORE UPDATE ON accounting_dimension_member_events BEGIN SELECT RAISE(ABORT,'accounting dimension member events are append-only'); END;
CREATE TRIGGER accounting_dimension_member_events_no_delete BEFORE DELETE ON accounting_dimension_member_events BEGIN SELECT RAISE(ABORT,'accounting dimension member events are append-only'); END;
